/**
 * As fontes do produto, dentro do proprio processo.
 *
 * POR QUE ELAS ESTAO AQUI DENTRO, e nao vindo do Google Fonts como no painel
 * web: a politica de seguranca de conteudo deste console e
 * `style-src 'self'`, entao a folha do Google (fonts.googleapis.com) e
 * bloqueada antes de carregar. Abrir `unsafe-inline` ou soltar `style-src`
 * para um dominio de terceiro e justamente a diretiva que faz a politica
 * deixar de valer, e ela nao se negocia por causa de tipografia.
 *
 * POR QUE EM BASE64 NUM MODULO, e nao como arquivo ao lado: a construcao deste
 * pacote e `tsc` puro, que copia `.ts` e mais nada. Um `.ttf` em
 * `src/` simplesmente nao chega ao `dist/`, e o console publicado abriria
 * com a pilha do sistema, que e a fonte errada justamente no ambiente que o
 * cliente ve. Bytes dentro de um modulo viajam com o `dist` sem depender de
 * ninguem lembrar de copia-los.
 *
 * COMPRIMIDAS COM BROTLI antes do base64, e descomprimidas uma vez na carga do
 * modulo. Sao 300 KB de fonte que viram 128 KB de brotli, e o navegador
 * continua recebendo o `.ttf` inteiro.
 *
 * TRES FACES, e nao as cinco que o aplicativo de campo embarca. Cada uma tem
 * lugar conhecido nesta tela: Work Sans 400 no corpo, Work Sans 600 em titulo
 * e botao, Roboto Mono 400 em numero de tabela, identificador e senha inicial.
 * Peso sem uso e peso que ninguem percebe faltar, e cada um custa 40 KB.
 *
 * PROCEDENCIA E LICENCA: os arquivos sao os mesmos de
 * `apps/campo/assets/fontes`, baixados do servico oficial de fontes do Google
 * em 13/09/2026 (Work Sans v24, Roboto Mono v31). Licenca SIL Open Font
 * License 1.1, texto integral em `apps/campo/assets/fontes/OFL-WorkSans.txt`
 * e `OFL-RobotoMono.txt`. A OFL permite embarcar e redistribuir junto com o
 * produto.
 *
 * ARQUIVO GERADO. O texto em base64 abaixo nao se edita a mao: ele sai dos
 * `.ttf` de `apps/campo/assets/fontes`, e trocar a fonte do produto e
 * regerar este arquivo a partir de la.
 */
import { brotliDecompressSync } from "node:zlib";

/** O que o navegador recebe: caminho, tipo e os bytes ja descomprimidos. */
export type FaceDeFonte = {
  caminho: string;
  tipo: string;
  bytes: Buffer;
};

function descomprimir(base64: string): Buffer {
  return brotliDecompressSync(Buffer.from(base64.replace(/\s+/g, ""), "base64"));
}

